      const pin = typeof offPinned_ === 'function' ? offPinned_() : new Set();
      drop = [...LIB.disk.values()].filter(r => !pin.has(r.id)).sort((a, b) => a.at - b.at).slice(0, LIB.disk.size - LIB_DISK_MAX).map(r => r.id);
